def style_ax(ax, grid_axis="y"):
    """Applica uno stile pulito e coerente a un asse matplotlib."""
    ax.spines['top'].set_visible(False)
    ax.spines['right'].set_visible(False)
    ax.spines['left'].set_color(PALETTE["grid"])
    ax.spines['bottom'].set_color(PALETTE["grid"])
    ax.grid(True, axis=grid_axis, linestyle="-", linewidth=0.6, color=PALETTE["grid"], alpha=0.9)
    ax.set_axisbelow(True)


def color_by_keyword(val, mapping, default_color=None):
    """Restituisce uno stile CSS in base a parole chiave contenute nel valore."""
    s = str(val)
    for keyword, color in mapping.items():
        if keyword in s:
            return f'background-color: {color}1A; color: {color}; font-weight: 600;'
    if default_color:
        return f'background-color: {default_color}1A; color: {default_color}; font-weight: 600;'
    return ''


def style_azione(val):
    return color_by_keyword(val, {
        "COMPRA": PALETTE["positive"],
        "VENDI": PALETTE["negative"],
        "MANTIENI": PALETTE["neutral"],
    })


def style_diversificazione(val):
    return color_by_keyword(val, {
        "Ottima": PALETTE["positive"],
        "Moderata": "#D97706",
        "Elevata": PALETTE["negative"],
    })


def style_giudizio_overlap(val):
    return color_by_keyword(val, {
        "Bassa": PALETTE["positive"],
        "Moderata": "#D97706",
        "Alta": PALETTE["negative"],
    })


def style_pnl(val):
    try:
        v = float(val)
    except (TypeError, ValueError):
        return ''
    if v > 0:
        return f'background-color: {PALETTE["positive"]}1A; color: {PALETTE["positive"]}; font-weight: 600;'
    elif v < 0:
        return f'background-color: {PALETTE["negative"]}1A; color: {PALETTE["negative"]}; font-weight: 600;'
    return ''


def build_allocation_chart(order, donut_threshold=8):
    """Costruisce il grafico di allocazione più adatto al numero di asset:
    - fino a 'donut_threshold' asset: ciambella con percentuali ed etichette leggibili;
    - oltre: barre orizzontali ordinate, con TUTTI gli asset elencati singolarmente
      (nessun raggruppamento in 'Altri'), molto più leggibili di una torta affollata."""
    labels_all = [t for t, v in order]
    sizes_all = [v for t, v in order]
    total = sum(sizes_all)
    n = len(order)

    if n <= donut_threshold:
        colors = [PALETTE["cycle"][i % len(PALETTE["cycle"])] for i in range(n)]
        fig, ax = plt.subplots(figsize=(3.6, 3.6))

        def autopct_fmt(pct):
            return f"{pct:.0f}%" if pct >= 4 else ""

        wedges, texts, autotexts = ax.pie(
            sizes_all, labels=None, autopct=autopct_fmt, pctdistance=0.78, startangle=90,
            colors=colors, wedgeprops={'width': 0.42, 'edgecolor': 'white', 'linewidth': 2}
        )
        for at in autotexts:
            at.set_color('white')
            at.set_fontsize(8)
            at.set_fontweight('bold')
        legend_labels = [f"{l}  ({s/total*100:.1f}%)" for l, s in zip(labels_all, sizes_all)]
        ax.legend(wedges, legend_labels, loc='center left', bbox_to_anchor=(1.0, 0.5), fontsize=8, frameon=False)
        ax.set_title("Allocazione Attuale", fontsize=11, pad=8, color=PALETTE["primary_dark"])
        fig.tight_layout()
        return fig

    # Troppi asset per una torta leggibile: barre orizzontali con TUTTI gli asset, nessun raggruppamento
    display_items = order

    labels_b = [t for t, v in display_items][::-1]
    sizes_b = [v for t, v in display_items][::-1]
    colors_b = [PALETTE["cycle"][i % len(PALETTE["cycle"])] for i in range(len(display_items))][::-1]

    fig, ax = plt.subplots(figsize=(4.6, max(3.0, 0.38 * len(display_items))))
    pct_values = [s / total * 100 for s in sizes_b]
    bars = ax.barh(labels_b, pct_values, color=colors_b)
    max_pct = max(pct_values) if pct_values else 0
    for bar, pct in zip(bars, pct_values):
        ax.text(bar.get_width() + max_pct * 0.02, bar.get_y() + bar.get_height() / 2,
                f"{pct:.1f}%", va='center', fontsize=8, color=PALETTE["primary_dark"])
    ax.set_xlabel("Peso sul Totale (%)")
    ax.set_xlim(0, max_pct * 1.18 if max_pct > 0 else 1)
    style_ax(ax, grid_axis="x")
    ax.set_title("Allocazione Attuale", fontsize=11, pad=8, color=PALETTE["primary_dark"])
    fig.tight_layout()
    return fig


def metric_with_info(column, label, value, help_text, delta=None):
    """Mostra una metrica e, subito sotto, un elemento cliccabile che ne rivela il significato
    e l'utilità. Usa st.popover se disponibile (Streamlit recenti); altrimenti ricade su un
    expander, supportato praticamente da ogni versione di Streamlit."""
    if delta is not None:
        column.metric(label, value, delta)
    else:
        column.metric(label, value)

    if hasattr(column, "popover"):
        with column.popover("Cosa significa?", width="stretch"):
            st.write(help_text)
    else:
        with column.expander("Cosa significa?"):
            st.write(help_text)


def scroll_to_content():
    """Fa scorrere automaticamente la pagina fino all'inizio del contenuto della sezione
    selezionata, così è subito visibile che la sezione è stata caricata senza dover scorrere
    manualmente oltre la configurazione del portafoglio nella parte alta della pagina."""
    components.html(
        """
        <script>
        setTimeout(function() {
            var doc = window.parent.document;
            var el = doc.getElementById('content-start');
            if (el) {
                el.scrollIntoView({behavior: 'smooth', block: 'start'});
            }
        }, 120);
        </script>
        """,
        height=0
    )


def apply_cell_style(styler, func, subset):
    """Compatibilità tra versioni di pandas: usa .map() se disponibile (pandas >= 2.1),
    altrimenti ricade su .applymap() (versioni precedenti, dove .map() non esiste sullo Styler)."""
    if hasattr(styler, "map"):
        return styler.map(func, subset=subset)
    return styler.applymap(func, subset=subset)


