SAVE_DIR = Path("data")
SAVE_DIR.mkdir(exist_ok=True)
SAVE_FILE = SAVE_DIR / "portfolio_save.json"
TRANSACTIONS_FILE = SAVE_DIR / "transactions_save.json"


def save_portfolio_to_disk(df, targets, benchmark_ticker):
    try:
        df_to_save = df.copy()
        if "Data_Apertura" in df_to_save.columns:
            df_to_save["Data_Apertura"] = df_to_save["Data_Apertura"].apply(
                lambda x: str(x) if pd.notnull(x) else None
            )
        payload = {
            "portfolio": df_to_save.to_dict(orient="records"),
            "targets": targets,
            "benchmark": benchmark_ticker if benchmark_ticker else "",
            "saved_at": pd.Timestamp.now().isoformat()
        }
        SAVE_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception as e:
        st.sidebar.error(f"Errore nel salvataggio: {e}")
        return False


def load_portfolio_from_disk():
    if SAVE_FILE.exists():
        try:
            payload = json.loads(SAVE_FILE.read_text(encoding="utf-8"))
            df = pd.DataFrame(payload.get("portfolio", []))
            if not df.empty and "Data_Apertura" in df.columns:
                df["Data_Apertura"] = pd.to_datetime(df["Data_Apertura"], errors="coerce").dt.date
            targets = payload.get("targets", {})
            benchmark = payload.get("benchmark", "")
            saved_at = payload.get("saved_at")
            return df, targets, benchmark, saved_at
        except Exception as e:
            st.sidebar.error(f"Errore nel caricamento del salvataggio: {e}")
    return None, {}, "", None


def save_transactions_to_disk(df):
    try:
        df_to_save = df.copy()
        if "Data" in df_to_save.columns:
            df_to_save["Data"] = df_to_save["Data"].apply(lambda x: str(x) if pd.notnull(x) else None)
        payload = {
            "transactions": df_to_save.to_dict(orient="records"),
            "saved_at": pd.Timestamp.now().isoformat()
        }
        TRANSACTIONS_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        return True
    except Exception as e:
        st.error(f"Errore nel salvataggio del registro operazioni: {e}")
        return False


def load_transactions_from_disk():
    if TRANSACTIONS_FILE.exists():
        try:
            payload = json.loads(TRANSACTIONS_FILE.read_text(encoding="utf-8"))
            df = pd.DataFrame(payload.get("transactions", []))
            if not df.empty and "Data" in df.columns:
                df["Data"] = pd.to_datetime(df["Data"], errors="coerce").dt.date
            return df
        except Exception:
            pass
    return pd.DataFrame(columns=["Data", "Ticker", "Tipo", "Quantità", "Prezzo (€)"])


