def compute_cost_basis_from_transactions(tx_df):
    """Calcola, per ciascun ticker, il prezzo medio di carico (metodo del costo medio ponderato)
    e la data di apertura della posizione ancora in essere, elaborando le operazioni di
    acquisto/vendita in ordine cronologico. Se la posizione viene azzerata da vendite e poi
    riaperta, la data di apertura si aggiorna al nuovo acquisto."""
    if tx_df is None or tx_df.empty:
        return {}

    tx = tx_df.copy()
    tx["Data"] = pd.to_datetime(tx["Data"], errors="coerce")
    tx["Quantità"] = pd.to_numeric(tx["Quantità"], errors="coerce").fillna(0)
    tx["Prezzo (€)"] = pd.to_numeric(tx["Prezzo (€)"], errors="coerce").fillna(0)
    tx["Ticker"] = tx["Ticker"].astype(str).str.strip().str.upper()
    tx = tx.dropna(subset=["Data"])
    tx = tx[tx["Ticker"].notna() & (tx["Ticker"] != "") & (tx["Ticker"] != "NAN")]
    tx = tx.sort_values("Data")

    results = {}
    for ticker, group in tx.groupby("Ticker"):
        qty_held = 0.0
        total_cost = 0.0
        first_open_date = None

        for _, r in group.iterrows():
            if r["Tipo"] == "Acquisto":
                if qty_held <= 1e-9:
                    first_open_date = r["Data"]
                qty_held += r["Quantità"]
                total_cost += r["Quantità"] * r["Prezzo (€)"]
            elif r["Tipo"] == "Vendita":
                if qty_held > 1e-9:
                    avg_cost = total_cost / qty_held
                    total_cost -= min(r["Quantità"], qty_held) * avg_cost
                qty_held -= r["Quantità"]
                if qty_held <= 1e-9:
                    qty_held = 0.0
                    total_cost = 0.0
                    first_open_date = None

        if qty_held > 1e-9:
            results[ticker] = {
                "Quantità Netta": qty_held,
                "Prezzo Medio di Carico (€)": total_cost / qty_held,
                "Data Apertura": first_open_date.date() if first_open_date is not None else None
            }

    return results

