ISIN_PATTERN = re.compile(r'^[A-Z]{2}[A-Z0-9]{9}\d$')


def find_col_index(columns, keywords, fallback_idx=0):
    idx = next((i for i, c in enumerate(columns) if any(k in str(c).lower() for k in keywords)), None)
    if idx is None:
        return fallback_idx
    return idx


def find_col_index_optional(columns, keywords):
    """Come find_col_index, ma restituisce None se non trova nulla (invece di un indice di
    ripiego): usata per le colonne opzionali data apertura/prezzo di carico, dove 'non trovato'
    deve tradursi in 'Nessuna colonna' nel menu a tendina, non in una scelta casuale."""
    return next((i for i, c in enumerate(columns) if any(k in str(c).lower() for k in keywords)), None)


ALL_BROKER_KEYWORDS = sorted(set(
    k for kw in BROKER_KEYWORDS.values() for group in kw.values() for k in group
))


def read_raw_table(uploaded_file, file_name_lower):
    """Legge il file senza assumere dove si trovi l'intestazione (header=None),
    così da poterla individuare automaticamente anche se precede metadati o righe vuote."""
    if file_name_lower.endswith('.csv'):
        try:
            return pd.read_csv(uploaded_file, sep=None, engine='python', header=None, dtype=str)
        except Exception:
            uploaded_file.seek(0)
            return pd.read_csv(uploaded_file, sep=';', header=None, dtype=str)
    elif file_name_lower.endswith('.xlsx'):
        return pd.read_excel(uploaded_file, engine='openpyxl', header=None, dtype=str)
    else:
        return pd.read_excel(uploaded_file, engine='xlrd', header=None, dtype=str)


def detect_header_row(raw_df, keywords, max_scan=15):
    """Individua automaticamente la riga più probabile di intestazione tra le prime
    'max_scan' righe del file, anche se preceduta da titoli o righe vuote."""
    best_idx = 0
    best_score = -1.0
    n_scan = min(max_scan, len(raw_df))
    for i in range(n_scan):
        row_vals = [str(v).strip().lower() for v in raw_df.iloc[i].tolist() if pd.notna(v)]
        if not row_vals:
            continue
        keyword_score = sum(1 for v in row_vals for k in keywords if k in v)
        fill_ratio = len(row_vals) / max(1, raw_df.shape[1])
        score = keyword_score * 10 + fill_ratio
        if score > best_score:
            best_score = score
            best_idx = i
    return best_idx if best_score > 0 else 0


