@st.cache_data
def classify_ticker_live(ticker):
    """Classifica un ticker non presente nel catalogo curato, interrogando Yahoo Finance.
    Usato come ripiego dallo Screener del Portafoglio quando il titolo non è tra quelli noti."""
    try:
        info = yf.Ticker(ticker).info
        quote_type = info.get('quoteType', 'N/D')
        if quote_type == 'EQUITY':
            sector = info.get('sector') or 'Non Specificato'
            country = info.get('country') or 'N/D'
            return {"Categoria": f"Azionario - {sector}", "Area Geografica": country, "Tipologia": "Azione"}
        elif quote_type in ('ETF', 'MUTUALFUND'):
            category = info.get('category') or 'ETF/Fondo'
            return {"Categoria": category, "Area Geografica": "N/D", "Tipologia": "ETF"}
        elif quote_type != 'N/D':
            return {"Categoria": quote_type, "Area Geografica": "N/D", "Tipologia": quote_type}
        else:
            return {"Categoria": "Non Classificato", "Area Geografica": "N/D", "Tipologia": "N/D"}
    except Exception:
        return {"Categoria": "Non Classificato", "Area Geografica": "N/D", "Tipologia": "N/D"}


def classify_portfolio_ticker(ticker):
    """Classifica un ticker del portafoglio: usa prima il catalogo curato (etichette più
    consistenti), e solo se il titolo non è presente ricorre a Yahoo Finance in tempo reale."""
    if ticker in CATALOG_BY_TICKER:
        info = CATALOG_BY_TICKER[ticker]
        return {"Categoria": info["Categoria"], "Area Geografica": info["Area Geografica"], "Tipologia": info["Tipologia"], "Fonte": "Catalogo"}
    live = classify_ticker_live(ticker)
    live["Fonte"] = "Rilevato automaticamente"
    return live


